def comps(cells):
    cs=[];seen=set()
    for c in cells:
        if c in seen: continue
        q=deque([c]);cs.append([]);seen.add(c)
        while q:
            x=q.popleft();cs[-1].append(x)
            for dx in(-1,0,1):
                for dy in(-1,0,1):
                    n=(x[0]+dx,x[1]+dy)
                    if n in set(cells) and n not in seen: seen.add(n);q.append(n)
    return cs
