def f(g):
    from collections import deque
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=0 or seen[i][j]: continue
            q=deque([(i,j)]);seen[i][j]=True;cells=[]
            while q:
                x,y=q.popleft();cells.append((x,y))
                for dx in(-1,0,1):
                    for dy in(-1,0,1):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<h and 0<=ny<w and g[nx][ny]==0 and not seen[nx][ny]:
                            seen[nx][ny]=True;q.append((nx,ny))
            if len(cells)>=2:
                for x,y in cells: out[x][y]=8
    return out
